head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDSTF37711.xml';
scwin.regMode;
scwin.gIsurCd;
scwin.gSeq;
scwin.gChgBfafTpCd;
scwin.gDesignRsnCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    scwin.gSeq = frame.opener.scwin.gSeq;
    scwin.gIsurCd = frame.opener.scwin.gIsurCd;
    scwin.gChgBfafTpCd = frame.opener.scwin.gChgBfafTpCd;
    scwin.gDesignRsnCd = frame.opener.scwin.gDesignRsnCd;
    $c.stf.setObjectValue(txb_seq, scwin.gSeq);
    $c.stf.setObjectValue(txb_isur_cd, scwin.gIsurCd);
    $c.stf.setObjectValue(txb_chg_bfaf_tp_cd, scwin.gChgBfafTpCd);
    $c.stf.setObjectValue(txb_designRsnCd, scwin.gDesignRsnCd);
    $c.stf.showObj(txb_seq, false);
    $c.stf.showObj(txb_chg_bfaf_tp_cd, false);
    $c.stf.showObj(txb_designRsnCd, false);
};




//선택한 정보 값 셋팅
scwin.fn_ReadInfo = function() {
    var url = "/ConfrmProcs.do?method=selectDesignRsnInfo" + "&inputMessageId=DESIGN_RSN_INFO" + "&CPOC_SEQ=" + scwin.gSeq + "&CPOC_CHG_BFAF_TP_CD=" + scwin.gChgBfafTpCd + "&CPOC_DESIGN_RSN_CD=" + scwin.gDesignRsnCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.reset();
};


//초기화
scwin.fn_Init = function() {
    if (scwin.gDesignRsnCd == "4" || scwin.gDesignRsnCd == "5" || scwin.gDesignRsnCd == "6") {
        $c.stf.showObj(img_cls_dd, true);
        edt_strt_dd.setReadOnly(false);
    } else {
        $c.stf.showObj(img_cls_dd, false);
        edt_strt_dd.setReadOnly(true);
    }

    // 가우스헤더 셋팅
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DESIGN_RSN_INFO";
    dts_MASTER.reset();
    dts_MASTER.insertRow();
};


//saveVar의 값이 비어있을경우 sVar를 그대로 리턴,
//비어있지 않을경우 ','를 붙여 리턴
scwin.fn_StrAppend = function(saveVar, sVar) {
    if (saveVar == '') {
        return sVar;
    } else {
        return "," + sVar;
    }
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};



//등록 및 수정 처리
scwin.fn_Insert = function() {
    var vStrt_dd = $c.stf.getObjectValue(edt_strt_dd);

    // 매매일 체크
    if (!$c.lc.fn_TrHoldyYn(dts_checkDD, vStrt_dd)) {
        edt_strt_dd.focus();
        return;
    }
    if (!scwin.checkMaxLength1(txb_design_rsn_dsc, 100, "비고")) {
        //txb_design_rsn_dsc.value = "";
        txb_design_rsn_dsc.focus();
        return false;
    }


    // 메세지 설정
    var tmpStr;
    tmpStr = "저장 하시겠습니까?";
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_inquiry.Action = "/ConfrmProcs.do?method=updateDesignRsn&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput1=dts_MASTER)";
        trs_inquiry.Post();
    }
};
scwin.img_cls_dd_onclick = function() {
    popUpCalendar2(edt_strt_dd);
};
scwin.trs_inquiry_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_inquiry_OnFail = function() {
    $c.win.alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {

};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_GetParentValue();
    scwin.fn_Init();

    //if(regMode == 'MOD'){ 
    scwin.fn_ReadInfo(); //기본정보 불러오기
    //}

    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
